"""Build the static Vietnamese catalog. Product data is maintained in content.json."""
from pathlib import Path
import html,json,re
from datetime import date
from PIL import Image,ImageOps
R=Path(__file__).parent;D=R/'dist';A=D/'assets';A.mkdir(parents=True,exist_ok=True)
C=json.loads((R/'content.json').read_text());B=C['business'];P=C['products'];W=C['wineFamilies'];families={x['slug']:x for x in W};cats={x['slug']:x for x in P}
originals=json.loads((R.parent/'images.json').read_text()) if (R.parent/'images.json').exists() else []
for family in W:
 for i in family['images']:
  if originals:
   im=ImageOps.exif_transpose(Image.open(R.parent/originals[i])).convert('RGB');im.thumbnail((960,1280));im.save(A/f'photo-{i:02d}.webp','WEBP',quality=82)
def e(x):return html.escape(str(x),quote=True)
def href(s=''):return base+s+('/' if s else '')
def link(s,t,c=''):return f'<a class="{c}" href="{href(s)}">{t}</a>'
def call(t='Gọi 0972 686 765',c='button'):return f'<a class="{c}" href="tel:+84972686765">{t}</a>'
def pic(i,alt,c='',eager=False):return f'<img class="{c}" src="{base}assets/photo-{i:02d}.webp" width="960" height="1280" alt="{e(alt)}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'
mark='<svg viewBox="0 0 64 64" fill="none" aria-hidden="true"><path d="M12 24 22 32 32 17 42 32 52 24 47 45H17L12 24Z" stroke="currentColor" stroke-width="1.5"/><path d="M20 50H44M32 17V9M28 12H36" stroke="currentColor"/><circle cx="32" cy="32" r="3" fill="currentColor"/></svg>'
logo=f'<span class="brand-mark">{mark}</span><span class="brand-type">SÂM NỮ HOÀNG<small>NGỰ VỊ · NỮ HOÀNG TƯU</small></span>'
def crumb(items):return '<nav class="breadcrumbs" aria-label="Đường dẫn">'+link('','Trang chủ')+''.join('<span aria-hidden="true">/</span>'+ (link(s,t) if s else f'<span aria-current="page">{t}</span>') for s,t in items)+'</nav>'
def title(k,t,d,items=None):return f'<section class="page-title container">{crumb(items or [(None,re.sub("<[^>]+>"," ",t))])}<p class="eyebrow">{k}</p><h1>{t}</h1><p class="lead">{d}</p></section>'
def heading(k,t,d='',cta=''):return f'<div class="section-heading reveal"><div><p class="eyebrow">{k}</p><h2>{t}</h2></div><div class="heading-side">'+(f'<p>{d}</p>' if d else '')+cta+'</div></div>'
def winecard(w):
 return f'<article class="wine-card reveal" data-wine="{w["slug"]}" data-search="{e(w["name"])}"><a class="wine-image" href="{href("san-pham/ruou-sam/"+w["slug"])}">{pic(w["cover"],w["name"]+" — Ngự Vị Nữ Hoàng Tưu")}<span class="image-arrow" aria-hidden="true">↗</span></a><div class="card-meta"><span>{w["label"]}</span><span>{len(w["images"]):02d} GÓC ẢNH</span></div><h3>{link("san-pham/ruou-sam/"+w["slug"],w["name"])}</h3><p>{w["desc"]}</p><div class="card-bottom">{link("san-pham/ruou-sam/"+w["slug"],"Xem quy cách ↗","underlink")}<span>Liên hệ báo giá</span></div></article>'
def categorycard(p):
 slug=p['slug'];visual=pic(40,'Trống rượu gỗ sồi') if slug=='ruou-sam' else f'<div class="category-graphic art-{slug}"><span>{p["number"]}</span><div class="botanical" aria-hidden="true">{sprout}</div><b>{p["short"]}</b><small>Hình ảnh đang cập nhật</small></div>'
 return f'<article class="category-card reveal" data-category="{slug}"><a class="category-image" href="{href("san-pham/"+slug)}">{visual}</a><p class="eyebrow">{p["label"]}</p><h3>{link("san-pham/"+slug,p["short"])}</h3><p>{p["desc"]}</p>{link("san-pham/"+slug,"Khám phá ↗","underlink")}</article>'
sprout='<svg viewBox="0 0 160 180" fill="none"><path d="M80 165V65M80 110C30 108 20 77 23 45C62 42 83 78 80 110ZM80 87C125 83 140 55 135 23C99 24 78 50 80 87ZM80 132C111 135 131 116 134 96C108 92 84 108 80 132ZM79 69C54 47 58 25 74 8C94 24 99 49 79 69Z" stroke="currentColor" stroke-width="1.2"/></svg>'
def sourcecards():return ''.join(f'<article class="source-card reveal"><p class="eyebrow">{e(s["publisher"])}</p><h3><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">{e(s["title"])}</a></h3><div><time>{e(s["date"])}</time><a href="{e(s["url"])}" target="_blank" rel="noopener noreferrer">Đọc tại nguồn ↗</a></div></article>' for s in C['sources'])
def region():return f'<div class="region-grid"><article class="region-card reveal"><span class="region-index">01 / VÙNG TRỒNG</span><h3>Sóc Sơn</h3><p>Hà Nội</p><div class="area">2 <span>ha</span></div></article><article class="region-card reveal"><span class="region-index">02 / VÙNG TRỒNG</span><h3>Ứng Hòa</h3><p>Hà Nội</p><div class="area">1 <span>ha</span></div></article></div>'
def table(rows):return '<dl class="specs">'+''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in rows)+'</dl>'
def cta():return f'<section class="contact-band"><div class="container contact-band-inner reveal"><div><p class="eyebrow">TƯ VẤN THEO NHU CẦU</p><h2>Chọn quy cách.<br><em>Trao đổi cùng chúng tôi.</em></h2></div><div>{call("0972 686 765 ↗","hotline-large")}<p>Hộ kinh doanh cá thể Đỗ Thị Tuyết</p>{link("lien-he","Địa chỉ & thông tin liên hệ ↗","underlink")}</div></div></section>'
def home():
 return f'''<section class="hero"><div class="hero-text"><p class="eyebrow">SÂM NỮ HOÀNG / BỘ SƯU TẬP RƯỢU SÂM</p><div class="hero-rule"></div><h1>Ngự Vị<br><em>Nữ Hoàng Tưu.</em></h1><p class="hero-description">Năm kiểu dáng, nhiều lựa chọn quy cách.<br>Khám phá dấu ấn riêng của trống gỗ sồi,<br>bình thủy tinh, hồ lô và chai rượu sâm.</p><div class="hero-actions">{link('san-pham/ruou-sam','Khám phá bộ sưu tập ↗','button')}{call('Tư vấn quy cách','underlink')}</div><div class="hero-foot"><span class="hero-edition">01 <i>/ 05</i></span><span>TRỐNG RƯỢU GỖ SỒI<br><small>NGỰ VỊ NỮ HOÀNG TƯU</small></span><a href="#bo-suu-tap" aria-label="Cuộn tới bộ sưu tập">↓</a></div></div><div class="hero-photo">{pic(27,'Trống rượu Ngự Vị Nữ Hoàng Tưu bằng gỗ sồi, có vòi rót và chân đế',eager=True)}<div class="photo-label">GỖ SỒI <span>·</span> CHI TIẾT THỰC TẾ</div></div><span class="hero-vertical" aria-hidden="true">SÂM NỮ HOÀNG — HÀ NỘI</span></section>
<div class="collection-strip"><div class="container"><span>KHÁM PHÁ QUY CÁCH</span>{''.join(link('san-pham/ruou-sam/'+w['slug'],w['name']) for w in W)}</div></div>
<section class="container section" id="bo-suu-tap">{heading('NGỰ VỊ NỮ HOÀNG TƯU','Một dòng rượu.<br><em>Nhiều dấu ấn riêng.</em>','Từng kiểu bình, chai và trống rượu được giới thiệu bằng hình ảnh thực tế.',link('san-pham/ruou-sam','Toàn bộ bộ sưu tập ↗','underlink'))}<div class="wine-grid home-wines">{''.join(winecard(w) for w in W)}</div><p class="alcohol-note">Sản phẩm có cồn · Dành cho người từ 18 tuổi · Không sử dụng rượu bia khi lái xe.</p></section>
<section class="oak-feature"><div class="container oak-layout"><div class="oak-photo reveal">{pic(40,'Mặt bên trống gỗ sồi Ngự Vị Nữ Hoàng Tưu với đai kim loại')}<span>01 / GỖ SỒI</span></div><div class="oak-copy reveal"><p class="eyebrow">ĐIỂM NHẤN BỘ SƯU TẬP</p><h2>Sắc gỗ ấm.<br><em>Dáng trống riêng.</em></h2><p>Thân gỗ sồi, những đai kim loại và vòi rót đặt trên chân đế gỗ. Một quy cách nổi bật trong bộ sưu tập Ngự Vị Nữ Hoàng Tưu.</p><div class="detail-traits"><span>Gỗ sồi</span><span>Vòi rót</span><span>Chân đế</span></div>{link('san-pham/ruou-sam/trong-go-soi','Khám phá trống rượu gỗ sồi ↗','button outline')}<p class="fine">Liên hệ để lựa chọn dung tích và quy cách phù hợp.</p></div></div></section>
<section class="container section">{heading('DANH MỤC SẢN PHẨM','Từ sâm nguyên liệu<br><em>đến các dòng chế biến.</em>','Bốn nhóm sản phẩm của Sâm Nữ Hoàng.',link('san-pham','Xem danh mục ↗','underlink'))}<div class="category-grid">{''.join(categorycard(p) for p in P)}</div></section>
<section class="region-section"><div class="container region-layout"><div class="reveal"><p class="eyebrow">VÙNG TRỒNG TẠI HÀ NỘI</p><h2>Từ vùng trồng,<br><em>kết nối giá trị.</em></h2><p>Tổng diện tích trồng 3 ha, gồm 2 ha tại Sóc Sơn và 1 ha tại Ứng Hòa, Hà Nội.</p>{link('vung-trong','Tìm hiểu vùng trồng ↗','underlink')}</div>{region()}</div></section>
<section class="container section about-short reveal"><p class="eyebrow">VỀ CHÚNG TÔI</p><h2>Hộ kinh doanh cá thể<br><em>Đỗ Thị Tuyết.</em></h2><p>{e(B['address'])}.</p>{link('gioi-thieu','Thông tin hộ kinh doanh ↗','underlink')}</section>
<section class="container section sources-home">{heading('KIẾN THỨC & THAM KHẢO','Đọc thêm về Sâm Nữ Hoàng.',cta=link('kien-thuc','Tất cả nguồn tham khảo ↗','underlink'))}<div class="source-grid">{sourcecards()}</div></section>{cta()}'''
def collection():return title('BỘ SƯU TẬP RƯỢU SÂM','Ngự Vị<br><em>Nữ Hoàng Tưu.</em>','Khám phá năm kiểu bình, chai và trống rượu. Dung tích, giá bán và quy cách cụ thể được tư vấn theo từng mẫu.',[('san-pham','Sản phẩm'),(None,'Rượu sâm')])+f'<section class="container"><div class="collection-tools"><div class="filter-buttons"><button data-wine-filter="all" class="active" aria-pressed="true">Tất cả <span>05</span></button><button data-wine-filter="wood" aria-pressed="false">Gỗ sồi</button><button data-wine-filter="glass" aria-pressed="false">Thủy tinh</button></div><label class="search-label"><span>Tìm kiểu bình</span><input type="search" id="wine-search" placeholder="Ví dụ: hồ lô, gỗ sồi…" autocomplete="off"></label></div><p id="filter-status" class="fine" aria-live="polite">5 kiểu dáng trong bộ sưu tập</p><div class="wine-grid">'+''.join(winecard(w) for w in W)+f'</div><div id="no-results" class="empty-results" hidden>Chưa tìm thấy kiểu bình phù hợp. Thử từ khóa khác hoặc {call("gọi hotline","underlink")} để được tư vấn.</div><p class="alcohol-note">Dành cho người từ 18 tuổi. Không sử dụng rượu bia khi lái xe.</p></section>{cta()}'
def wine_detail(w):
 key=w['slug'];ims=w['images'];slug='san-pham/ruou-sam/'+key
 return f'<div class="container">{crumb([("san-pham","Sản phẩm"),("san-pham/ruou-sam","Rượu sâm"),(None,w["name"])])}</div><section class="container product-detail"><div class="product-gallery"><button class="main-photo" data-image="{base}assets/photo-{ims[0]:02d}.webp" data-caption="{e(w["name"])} — góc ảnh 1" aria-label="Phóng to ảnh {e(w["name"])}">{pic(ims[0],w["name"]+" — góc ảnh 1",eager=True)}<span>Phóng to ＋</span></button><div class="gallery-thumbnails" aria-label="Chọn góc ảnh">'+''.join(f'<button data-thumbnail="{base}assets/photo-{i:02d}.webp" data-caption="{e(w["name"])} — góc ảnh {n+1}" aria-label="Xem góc ảnh {n+1}" aria-pressed="{str(n==0).lower()}" class="{("selected" if n==0 else "")}">{pic(i,w["name"]+" — ảnh nhỏ "+str(n+1))}</button>' for n,i in enumerate(ims))+f'</div><p class="fine">{len(ims)} góc ảnh thực tế · Chọn ảnh nhỏ để xem chi tiết.</p></div><div class="product-info"><p class="eyebrow">NGỰ VỊ NỮ HOÀNG TƯU</p><h1>{w["name"]}</h1><p class="lead">{w["desc"]}</p><div class="trait-list">'+''.join(f'<span>{t}</span>' for t in w['features'])+f'</div>'+table([('Kiểu bao bì',w['name']),('Dung tích','Tư vấn theo quy cách'),('Nồng độ cồn','Liên hệ xác nhận'),('Giá bán',call('Liên hệ báo giá','underlink'))])+f'<div class="product-actions">{call("Tư vấn mẫu này ↗","button")}<button class="button secondary" data-add="{key}">Lưu mẫu quan tâm ＋</button></div><p class="fine">Các góc chụp giúp quan sát hình dáng và chi tiết. Dung tích và cấu hình sẵn có cần được xác nhận khi tư vấn.</p><p class="alcohol-note">Dành cho người từ 18 tuổi. Không sử dụng rượu bia khi lái xe.</p></div></section><section class="container section"><div class="detail-tabs"><a href="#dac-diem">Đặc điểm</a><a href="#tu-van">Quy cách & tư vấn</a><a href="#lien-quan">Kiểu dáng khác</a></div><div class="detail-reading" id="dac-diem"><p class="eyebrow">ĐẶC ĐIỂM QUAN SÁT TỪ ẢNH</p><h2>{w["name"]}</h2><p>{w["desc"]}</p><ul>'+''.join(f'<li>{t}.</li>' for t in w['features'])+f'</ul></div><div class="detail-reading" id="tu-van"><h2>Lựa chọn đúng quy cách.</h2><p>Trao đổi với hộ kinh doanh về dung tích mong muốn, số lượng và mục đích sử dụng. Hotline {call("0972 686 765","underlink")} hỗ trợ xác nhận từng mẫu, giá bán và giao nhận.</p><p>Thông tin thành phần, hướng dẫn bảo quản và sử dụng sẽ được bổ sung theo hồ sơ sản phẩm. Vui lòng xác nhận thông tin của đúng quy cách trước khi đặt hàng.</p></div><div id="lien-quan">{heading("CÙNG BỘ SƯU TẬP","Khám phá kiểu dáng khác.")}<div class="wine-grid related-grid">'+''.join(winecard(x) for x in W if x['slug']!=key)+'</div></div></section>'
def generic_product(p):
 return title(p['label'],p['name'],p['desc'],[('san-pham','Sản phẩm'),(None,p['short'])])+f'<section class="container generic-product"><div class="category-graphic art-{p["slug"]}"><div class="botanical">{sprout}</div><b>{p["short"]}</b><small>Hình ảnh sản phẩm đang cập nhật</small></div><div><p class="eyebrow">THÔNG TIN SẢN PHẨM</p><h2>Tư vấn theo<br><em>nhu cầu của bạn.</em></h2>'+table([('Quy cách','Đang cập nhật'),('Khối lượng','Đang cập nhật'),('Giá bán','Liên hệ tư vấn')])+f'<p>{p["note"]}</p><div class="product-actions">{call("Gọi tư vấn ↗")}<button class="button secondary" data-add="{p["slug"]}">Lưu quan tâm ＋</button></div></div></section>{cta()}'
def about():return title('HỘ KINH DOANH CÁ THỂ','Đỗ Thị Tuyết.<br><em>Sâm Nữ Hoàng.</em>','Giới thiệu sâm tươi, sâm khô, rượu sâm và cao sâm; kết nối nhu cầu tìm hiểu sản phẩm với thông tin từ hộ kinh doanh.')+f'<section class="container business-layout"><div class="business-seal reveal">{mark}<span>SÂM NỮ HOÀNG</span><small>HỘ KINH DOANH CÁ THỂ<br>ĐỖ THỊ TUYẾT</small></div><div class="reveal"><p class="eyebrow">THÔNG TIN HỘ KINH DOANH</p><h2>Thông tin rõ ràng.<br><em>Kết nối trực tiếp.</em></h2>'+table([('Tên hộ kinh doanh',e(B['name'])),('Địa chỉ',e(B['address'])),('Hotline',call('0972 686 765','underlink')),('Diện tích trồng','3 ha tại Hà Nội')])+f'<p>Ngự Vị Nữ Hoàng Tưu hiện được giới thiệu qua năm kiểu bình, chai và trống gỗ sồi. Các dòng sâm tươi, sâm khô và cao sâm sẽ tiếp tục được bổ sung thông tin chi tiết.</p></div></section><section class="container section">{heading("VÙNG TRỒNG","3 ha tại Hà Nội.",cta=link("vung-trong","Xem vùng trồng ↗","underlink"))}{region()}</section>{cta()}'
def regions():return title('VÙNG TRỒNG','Gắn với Hà Nội.<br><em>Từ Sóc Sơn đến Ứng Hòa.</em>','Tổng diện tích trồng 3 ha: 2 ha tại Sóc Sơn và 1 ha tại Ứng Hòa, Hà Nội.')+f'<section class="container">{region()}<div class="region-total reveal"><span>TỔNG DIỆN TÍCH TRỒNG</span><strong>3 <small>ha</small></strong><p>Hai địa điểm tại Hà Nội.</p></div><div class="detail-reading"><h2>Thông tin vùng trồng.</h2><p>Diện tích và địa điểm được cung cấp bởi hộ kinh doanh cá thể Đỗ Thị Tuyết. Hình ảnh vùng trồng, mùa vụ và thông tin canh tác chi tiết sẽ được bổ sung khi có tư liệu.</p><p>Địa chỉ liên hệ của hộ kinh doanh: {e(B["address"])}.</p>{call("Trao đổi về nguồn nguyên liệu ↗","button")}</div></section>{cta()}'
def contact():return title('LIÊN HỆ & TƯ VẤN','Trao đổi trực tiếp.<br><em>Chọn quy cách phù hợp.</em>','Liên hệ hộ kinh doanh cá thể Đỗ Thị Tuyết để tìm hiểu sản phẩm, xác nhận quy cách và báo giá.')+f'<section class="container contact-layout"><div><p class="eyebrow">HOTLINE</p>{call("0972 686 765 ↗","contact-phone")}<div class="contact-address"><h2>Hộ kinh doanh cá thể<br>Đỗ Thị Tuyết</h2><address>{e(B["address"])}.</address></div><p class="fine">Bạn có thể lưu các mẫu quan tâm bên cạnh và tải danh sách để thuận tiện trao đổi khi gọi.</p></div><div class="inquiry-panel"><p class="eyebrow">DANH SÁCH CỦA BẠN</p><h2>Mẫu quan tâm <span id="list-count">0</span></h2><div id="inquiry-list"></div><label for="inquiry-note">Dung tích, số lượng hoặc nội dung cần tư vấn</label><textarea id="inquiry-note" rows="4" placeholder="Ví dụ: trống gỗ sồi, số lượng mong muốn…"></textarea><button class="button" id="download-inquiry">Tải danh sách ↓</button><p class="fine">Danh sách chỉ lưu trên thiết bị của bạn, chưa được gửi tới hộ kinh doanh và chưa phải đơn hàng.</p></div></section>'
def library():return title('THƯ VIỆN HÌNH ẢNH','Quan sát từng chi tiết.<br><em>Khám phá từng kiểu dáng.</em>','48 ảnh sản phẩm thực tế, được sắp xếp theo năm nhóm bình, chai và trống rượu.')+f'<section class="container"><nav class="gallery-index" aria-label="Nhóm ảnh">'+''.join(f'<a href="#{w["slug"]}">{w["name"]} <span>{len(w["images"])}</span></a>' for w in W)+'</nav>'+''.join(f'<section class="gallery-group" id="{w["slug"]}">{heading("NGỰ VỊ NỮ HOÀNG TƯU",w["name"],cta=link("san-pham/ruou-sam/"+w["slug"],"Chi tiết quy cách ↗","underlink"))}<div class="photo-grid">'+''.join(f'<button class="photo-tile reveal" data-image="{base}assets/photo-{i:02d}.webp" data-caption="{e(w["name"])} — góc ảnh {n+1}" aria-label="Phóng to {e(w["name"])} — ảnh {n+1}">{pic(i,w["name"]+" — góc ảnh "+str(n+1))}<span>{n+1:02d} / ＋</span></button>' for n,i in enumerate(w['images']))+'</div></section>' for w in W)+'</section>'
def content(s):
 if s=='':return home()
